var links = document.querySelectorAll('a[href*="/p/"]');
var seen = {};
var list = [];
links.forEach(function(a) {
  var title = a.textContent.trim();
  var href = a.getAttribute('href');
  if (!title || !href || seen[href]) return;
  seen[href] = true;
  var url = href.startsWith('http') ? href : 'https://36kr.com' + href;
  list.push({ rank: list.length + 1, title: title, url: url });
});
return JSON.stringify(list.slice(0, 30));

var items = document.querySelectorAll('.ranking_bookList_item, [class*="ranking_book"], [class*="bookList"] li');
var list = [];
items.forEach(function(el, i) {
  var titleEl = el.querySelector('.ranking_bookList_title, [class*="title"]');
  var authorEl = el.querySelector('.ranking_bookList_author, [class*="author"]');
  var linkEl = el.querySelector('a');
  if (titleEl && i < 30) {
    list.push({
      rank: i + 1,
      title: titleEl.textContent.trim(),
      author: authorEl ? authorEl.textContent.trim() : '',
      url: linkEl ? linkEl.href : '',
    });
  }
});
return JSON.stringify(list);

var items = document.querySelectorAll('[class*="hot-board"] a, [class*="hotBoard"] a, [class*="HotBoard"] a');
if (!items.length) items = document.querySelectorAll('a[href*="/trending/"]');
var seen = {};
var list = [];
items.forEach(function(el) {
  var title = el.textContent.trim();
  var href = el.href || '';
  if (title && title.length > 2 && title.length < 50 && !seen[title]) {
    seen[title] = true;
    list.push({
      rank: list.length + 1,
      title: title,
      url: href,
    });
  }
});
return JSON.stringify(list.slice(0, 30));

var items = document.querySelectorAll('[data-testid="edinburgh-card"], .gs-c-promo, article');
var list = [];
items.forEach(function(el, i) {
  var t = el.querySelector('h2, h3, [data-testid="card-headline"]');
  var a = el.querySelector('a');
  if (t && list.length < 20) list.push({rank: list.length+1, title: t.textContent.trim(), url: a ? a.href : ''});
});
return JSON.stringify(list);
